import '../styles/ShoppingList.css';
import { itemList } from '../datas/itemList';


function ShoppingList({ cart, updateCart }) {
  const sizeRange = ['M', 'L']

  function addToCart(name, price) {
    const existingItem = cart.find(item => item.name === name);
    if (existingItem) {
      const updatedCart = (cart.map((item) =>
        item.name === name ? { ...item, amount: item.amount + 1 } : item
      ));
      updateCart(updatedCart);
    } else {
      updateCart([...cart, { name, price, amount: 1 }]);
    }
  }

  return (
    <div className="panel panel--list">
      <h2 className="panel__title">Boutique</h2>
      <ul className="panel__list">
        {itemList.map((item) => (
          <li className='panel__item' key={item.id ?? item.name}>
            {/* <Article {...item}/> */}
            {item.cover ? (
              <img className='panel__media' src={item.cover} alt={item.name} />
            ) : (
              <div className="panel__media panel__media--placeholder" />
            )}
            <div className="panel__meta">
              <div>Name : {item.name}</div>
              {item.size && <div>Taille : {item.size}</div>}
              <div>Comfort : {item.comfort}</div>
              <div>Price : {item.price} €</div>
              {item.onSale && <span className="badge">En soldes</span>}
            </div>
            <button className="btn btn--ghost" onClick={() => addToCart(item.name, item.price)}>Ajouter</button>
          </li>
        ))}
      </ul>
    </div>
  )
}




export default ShoppingList
